import sqlite3, os, json, datetime, sys

db = os.path.join(os.environ['LOCALAPPDATA'], 'Temp', 'opencode', 'dbcopy', 'opencode.db')
c = sqlite3.connect(db)
c.row_factory = sqlite3.Row
sid = sys.argv[1] if len(sys.argv) > 1 else 'ses_ea0e0eca9ffe9iQbvW2lpMnmFz'

def ts(v):
    if not v: return None
    try:
        return datetime.datetime.fromtimestamp(v/1000).strftime('%H:%M:%S')
    except Exception:
        return v

rows = list(c.execute("select id,type,seq,time_created,data from session_message where session_id=? order by seq", (sid,)))
print("total messages:", len(rows))
print("types:", {})
from collections import Counter
print(Counter(r['type'] for r in rows))
# print last 40
for r in rows[-45:]:
    d = json.loads(r['data']) if r['data'] else {}
    t = r['type']
    summary = ''
    if t == 'assistant':
        parts = d.get('content') or d.get('parts') or []
        bits=[]
        for p in parts:
            pt = p.get('type')
            if pt=='text': bits.append('TEXT: '+(p.get('text') or '')[:400].replace('\n',' | '))
            elif pt=='tool': bits.append('TOOL: '+str(p.get('tool'))+' '+json.dumps(p.get('state',{}).get('input',{}))[:500])
            elif pt=='step-start': bits.append('STEP-START')
            elif pt=='step-finish': bits.append('STEP-FINISH tokens='+str(p.get('tokens')))
            elif pt=='reasoning': bits.append('REASON: '+(p.get('text') or '')[:200].replace('\n',' | '))
            else: bits.append(pt or '?')
        summary=' ;; '.join(bits)
    elif t == 'user':
        parts = d.get('content') or d.get('parts') or []
        summary = ' '.join((p.get('text') or '')[:300] for p in parts if p.get('type')=='text')
    elif t == 'tool':
        summary = json.dumps(d)[:400]
    else:
        summary = json.dumps(d)[:400]
    print(f"[{ts(r['time_created'])}] seq={r['seq']} {t}: {summary}")

