function New-Bar([double]$pct, [int]$width = 24) {
    if ($pct -lt 0) { $pct = 0 }
    if ($pct -gt 1) { $pct = 1 }
    $n = [int][math]::Round($pct * $width)
    if ($n -lt 0) { $n = 0 }
    if ($n -gt $width) { $n = $width }
    $full = $script:BAR_FULL * $n
    $empty = $script:BAR_EMPTY * ($width - $n)
    Write-Output ("DEBUG n=$n fullType=$($full.GetType().Name) fullLen=$($full.Length) emptyLen=$($empty.Length)")
    return ($full + $empty)
}
$bar = New-Bar 0.93 24
Write-Output ("BAR=[" + $bar + "] len=" + $bar.Length)
Write-Host ('HOST=[' + $bar + ']')
